  '1. Install on this computer': '1. Installera på den här datorn',
  'Run the official installer on the runtime host, then refresh status. It downloads and installs CuaDriver; no Cua account is required.':
    'Kör det officiella installationsprogrammet på runtime-värden och uppdatera sedan statusen. Det hämtar och installerar CuaDriver; inget Cua-konto krävs.',
  'Minimal Linux systems need libxi6 and at-spi2-core. GNOME needs Cua’s bundled WinRects helper; see the installation guide.':
    'Minimala Linux-system behöver libxi6 och at-spi2-core. GNOME behöver Cua:s medföljande WinRects-hjälpprogram. Se installationsguiden.',
