  'Save the computer-use switch for automatic dovo_cua MCP on new writable turns. No manual MCP registration is needed. Install the optional official skill pack; installation links detected agents on this computer.':
    'Spara datoranvändningsreglaget för automatisk dovo_cua MCP i nya skrivbara agentomgångar. Manuell MCP-registrering behövs inte. Installera det valfria officiella färdighetspaketet; installationen länkar identifierade agenter på den här datorn.',
  'Opt-in, encrypted, metadata-only history. Enable may restart the daemon. Disable keeps recorded data; pause temporarily stops recording. Unsupported builds report an error. Data stays on the runtime host; View recent history retrieves up to 20 events here.':
    'Valfri, krypterad historik med endast metadata. Aktivering kan starta om daemonen. Inaktivering behåller inspelade data; paus stoppar inspelningen tillfälligt. Versioner som inte stöds visar ett fel. Data finns kvar på runtime-värden; Visa senaste historik hämtar upp till 20 händelser hit.',
