  "Runs each new thread's agent, its commands and its terminals in a local Docker or Podman container. Only the checkout and the selected harness login are mounted. Running threads keep their setting.":
    'Kör agenten för varje nytt samtal, dess kommandon och dess terminaler i en lokal Docker- eller Podman-container. Bara arbetskopian och den valda agentens inloggning monteras. Pågående samtal behåller sin inställning.',
