  'The agent, its commands and its terminals run in a container. Only this checkout and the harness login are mounted.':
    'Agenten, dess kommandon och dess terminaler körs i en container. Bara den här arbetskopian och agentens inloggning monteras.',
  'Holds new work that runs without your message once its estimated cost reaches the limit. This covers Bot follow-ups, Bot routine steps, scheduled messages and child agents. Each thread or Bot counts with its child agents. A routine without a Bot starts a new count on each run. Set its own limits in Monitoring and limits. Your next message or Continue resets the count. Turns without a price also hold work. A running turn always finishes.':
    'Pausar nytt arbete som körs utan ditt meddelande när den uppskattade kostnaden når gränsen. Det gäller uppföljningar från Botar, rutinsteg i en Bot, schemalagda meddelanden och underagenter. Varje tråd eller Bot räknas tillsammans med sina underagenter. En rutin utan Bot börjar en ny räkning vid varje körning. Ange dess egna gränser under Övervakning och gränser. Ditt nästa meddelande eller Fortsätt nollställer räkningen. Turer utan pris pausar också arbete. En pågående tur slutförs alltid.',
